ALTER TABLE recettes_alchimie ADD COLUMN IF NOT EXISTS duree text;
INSERT INTO recettes_alchimie (nom,description,formule,effet,ingredients,niveau_requis,cout_xp,est_actif,type,duree) SELECT $hv$Catalyseur à potion$hv$,$hv$Composante de base requise pour fabriquer une potion.$hv$,$hv$Fundamentum Vitae Potio$hv$,$hv$Crée un catalyseur à potion.$hv$,$hv${"2 doses du même ingrédient au choix : Anys, Batrus, Girof, Nagro, Verda, Alys, Palos ou Huile de Mouf": 1, "manipulations": ["préparer l'ingrédient selon sa manip propre", "filtrer ou décanter", "repos puis mise en fiole", "labo 5 min"]}$hv$::jsonb,2,3,true,$hv$potion$hv$,$hv$Jusqu'à utilisation ou fin d'année de jeu.$hv$ WHERE NOT EXISTS (SELECT 1 FROM recettes_alchimie WHERE nom=$hv$Catalyseur à potion$hv$);
INSERT INTO recettes_alchimie (nom,description,formule,effet,ingredients,niveau_requis,cout_xp,est_actif,type,duree) SELECT $hv$Catalyseur à poison$hv$,$hv$Composante de base requise pour fabriquer un poison.$hv$,$hv$Fundamentum Nox Venenum$hv$,$hv$Crée un catalyseur à poison.$hv$,$hv${"2 doses du même ingrédient au choix : Noligraf, Poulfis, Poudre d'Alsase, Sablon, Ambre, Agline ou Liche": 1, "manipulations": ["préparer l'ingrédient selon sa manip propre", "verser lentement (éviter contact peau)", "brassage contrôlé", "labo 5 min"]}$hv$::jsonb,2,3,true,$hv$potion$hv$,$hv$Jusqu'à utilisation ou fin d'année de jeu.$hv$ WHERE NOT EXISTS (SELECT 1 FROM recettes_alchimie WHERE nom=$hv$Catalyseur à poison$hv$);
INSERT INTO recettes_alchimie (nom,description,formule,effet,ingredients,niveau_requis,cout_xp,est_actif,type,duree) SELECT $hv$Catalyseur magique$hv$,$hv$Composante de base pour parchemins et produits magiques.$hv$,$hv$Fundamentum Scriptura Arcanum$hv$,$hv$Crée un catalyseur magique.$hv$,$hv${"2 doses du même ingrédient au choix : Ganos, Ortie, Pied de Grumpf, Silice, Calyre ou Ficol": 1, "manipulations": ["préparer l'ingrédient selon sa manip propre", "appliquer sur support (instrument non métallique)", "activation au labo", "labo 5 min"]}$hv$::jsonb,2,3,true,$hv$potion$hv$,$hv$Jusqu'à utilisation ou fin d'année de jeu.$hv$ WHERE NOT EXISTS (SELECT 1 FROM recettes_alchimie WHERE nom=$hv$Catalyseur magique$hv$);
UPDATE recettes_alchimie SET type='potion' WHERE type='autre';
