fois la minute écoulée ou les trois sorts utilisés, la potion cesse de faire effet.$hv$),($hv$Potion de mysticisme$hv$,$hv$Effet instantané$hv$),($hv$Potion de peau de marbre$hv$,$hv$1 heure ou jusqu'à déclenchement$hv$),($hv$Potion de régénération$hv$,$hv$Effet instantané$hv$),($hv$Potion de souffle draconique$hv$,$hv$Effet instantané.$hv$)) AS m(nom,duree) WHERE r.nom=m.nom;
ALTER TABLE recettes_alchimie DROP CONSTRAINT IF EXISTS recettes_alchimie_type_check;
ALTER TABLE recettes_alchimie ADD CONSTRAINT recettes_alchimie_type_check CHECK (type IN ('potion','poison'));